preConditionHook:
// Level rejected from above (Brian's notes P1a, triage row P1). The P1 visit
// scan: a VISIT is a bar kk bars ago, minGap <= kk <= lookback, whose low..high
// range contains the current close (inclusive, el_le/el_ge). At least minVisits
// visits are required. Upper-wick visit: close[0] strictly above the visit's
// body top; lower-wick visit: strictly below its body bottom. SHORT when at
// least wickFraction of the visits are upper-wick visits; LONG mirrors on
// lower-wick visits. EL's MaxList/MinList select between open and close --
// tick-grid prices, the scope their ACCEPTED row allows -- so plain
// comparisons stand in (AverageUpperTailFraction's form).
visitCount = 0;
lowerWickVisits = 0;
upperWickVisits = 0;
for (kk = (int)minGap; kk <= (int)lookback; ++kk) {
    if (el_le(low[kk], close[0]) && el_ge(high[kk], close[0])) {
        visitCount = visitCount + 1;
        bodyTop = open[kk];
        if (close[kk] > bodyTop) bodyTop = close[kk];
        bodyBottom = open[kk];
        if (close[kk] < bodyBottom) bodyBottom = close[kk];
        if (el_lt(close[0], bodyBottom)) lowerWickVisits = lowerWickVisits + 1;
        if (el_gt(close[0], bodyTop)) upperWickVisits = upperWickVisits + 1;
    }
}
enoughVisits = el_ge(visitCount, minVisits) && el_gt(visitCount, 0);
